const root=$input.first().json||{};
const checks=root.checks || root.input?.checks || [];
if(!Array.isArray(checks)||!checks.length) return [{json:{success:false,component_id:'C6-E',component_version:'v1',health:{status:'unknown',score:0,checks:[]},error:{code:'NO_HEALTH_CHECKS',message:'checks[] is required.'},next_action:'supply_runtime_checks'}}];
const normalized=checks.map((c,i)=>({name:c.name||`check_${i+1}`,status:['pass','warn','fail'].includes(c.status)?c.status:'warn',detail:c.detail||null,latency_ms:Number(c.latency_ms)||null,critical:c.critical===true,source:c.source||null}));
let score=100;for(const c of normalized){if(c.status==='fail') score-=c.critical?35:20;else if(c.status==='warn') score-=8;}score=Math.max(0,score);
const criticalFail=normalized.some(c=>c.status==='fail'&&c.critical);const anyFail=normalized.some(c=>c.status==='fail');const anyWarn=normalized.some(c=>c.status==='warn');const status=criticalFail?'down':anyFail?'degraded':anyWarn?'warning':'healthy';
return [{json:{success:true,component_id:'C6-E',component_version:'v1',health:{status,score,checks:normalized,passed:normalized.filter(c=>c.status==='pass').length,warnings:normalized.filter(c=>c.status==='warn').length,failed:normalized.filter(c=>c.status==='fail').length},manual_review_required:status!=='healthy',next_action:status==='healthy'?'integration_health_passed':'repair_failed_checks',error:null}}];
